import { useState, useEffect, useRef, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Button, IconButton, Typography, useTheme, CircularProgress, Tooltip } from "@mui/material";
import { tokens } from "../../theme";
import Header from "../../components/Header";
import TimeRangeSelector from "../../components/TimeRangeSelector";
import { fetchDashboardData } from "../../services/dataService";
import ReportProblemOutlinedIcon from "@mui/icons-material/ReportProblemOutlined";
import RefreshIcon from "@mui/icons-material/Refresh";
import UndoIcon from "@mui/icons-material/Undo";
import HomeIcon from "@mui/icons-material/Home";
import FlightIcon from "@mui/icons-material/Flight";
import FlagIcon from "@mui/icons-material/Flag";
import WarningIcon from "@mui/icons-material/Warning";
import CampaignIcon from "@mui/icons-material/Campaign";
import LineChart from "../../components/LineChart";
import BarChart from "../../components/BarChart";
import PieChart from "../../components/PieChart";

import StatBox from "../../components/StatBox";
import ProgressCircle from "../../components/ProgressCircle";

const Dashboard = () => {
  const theme = useTheme();
  const colors = tokens(theme.palette.mode);
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [timeRange, setTimeRange] = useState("24h");
  const [dashboardData, setDashboardData] = useState(null);
  const lineChartRef = useRef();

  const loadData = useCallback(
    async (range = timeRange) => {
      try {
        const data = await fetchDashboardData(range);
        setDashboardData(data);
        setIsLoading(false);
        setIsRefreshing(false);
      } catch (error) {
        console.error("Failed to load data:", error);
        setIsLoading(false);
        setIsRefreshing(false);
      }
    },
    [timeRange] // add any other values used inside loadData, removed fetchDashboardData because it is not yet a dependency
  );
  
  const handleRefresh = () => {
    setIsRefreshing(true);
    loadData();
  };
  
  const handleTimeRangeChange = (range) => {
    setTimeRange(range);
    setIsRefreshing(true);
    loadData(range);
  };
  
  useEffect(() => {
    loadData();
    
    // Auto-refresh every 35 seconds (offset from 30s upload for fresh data)
    const refreshInterval = setInterval(() => {
      loadData();
    }, 35000); // 35 seconds
    
    return () => clearInterval(refreshInterval);
  }, [loadData]);
  
  // Loading screen
  if (isLoading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="100vh"
        sx={{
          backgroundColor: theme.palette.mode === "dark" 
            ? colors.primary[500] 
            : "#fcfcfc",
        }}
      >
        <Box textAlign="center">
          <CircularProgress
            size={60}
            sx={{
              color: colors.orangeAccent[500],
              mb: "20px",
            }}
          />
          <Typography
            variant="h4"
            color={theme.palette.mode === "dark" 
              ? colors.grey[100] 
              : colors.grey[100]}
            fontWeight="600"
          >
            Loading Dashboard...
          </Typography>
          <Typography
            variant="h6"
            color={theme.palette.mode === "dark" 
              ? colors.grey[300] 
              : colors.grey[400]}
            sx={{ mt: "10px" }}
          >
            Fetching data from your device
          </Typography>
        </Box>
      </Box>
    );
  }

  return (
    <Box m="20px">
      {/* HEADER */}
      <Box display="flex" justifyContent="space-between" alignItems="center">
        <Box>
          <Header title="DASHBOARD" subtitle="Welcome to the Skysentinel DashBoard by FrankenBits of Perfect Storm Laboratories: Where impossible innovations become reality! " />
          {dashboardData?.lastUpdated && (
            <Typography variant="body2" color={colors.grey[300]} sx={{ mt: 1 }}>
              Last updated: {dashboardData.lastUpdated}
            </Typography>
          )}
        </Box>
        
        <Box display="flex" flexDirection="column" alignItems="flex-end" gap="10px">
          <Box display="flex" alignItems="center" gap="15px">
            <TimeRangeSelector 
              selectedRange={timeRange} 
              onRangeChange={handleTimeRangeChange} 
            />
            <IconButton 
              onClick={handleRefresh}
              disabled={isRefreshing}
              sx={{
                backgroundColor: colors.primary[500],
                color: colors.grey[100],
                "&:hover": { backgroundColor: colors.primary[600] },
                "&:disabled": { opacity: 0.6 }
              }}
            >
              <RefreshIcon sx={{ 
                fontSize: "20px",
                animation: isRefreshing ? "spin 1s linear infinite" : "none",
                "@keyframes spin": {
                  "0%": { transform: "rotate(0deg)" },
                  "100%": { transform: "rotate(360deg)" }
                }
              }} />
            </IconButton>
          </Box>
          <Box display="flex" gap="10px">
            <Button
              onClick={() => navigate("/")}
              sx={{
                backgroundColor: theme.palette.mode === "dark" 
                  ? colors.primary[500] 
                  : colors.blueAccent[500],
                color: theme.palette.mode === "dark" 
                  ? colors.grey[100] 
                  : "#ffffff",
                fontSize: "14px",
                fontWeight: "bold",
                padding: "10px 20px",
                "&:hover": {
                  backgroundColor: theme.palette.mode === "dark" 
                    ? colors.primary[600] 
                    : colors.blueAccent[600],
                },
              }}
            >
              <HomeIcon sx={{ mr: "10px" }} /> Home
            </Button>
            <Button
              onClick={() => window.open("https://www.faa.gov/about/office_org/field_offices/fsdo/lou/Low_Flying_Aircraft_Report_Form.pdf", "_blank")}
              sx={{
                backgroundColor: colors.blueAccent[700],
                color: colors.grey[100],
                fontSize: "14px",
                fontWeight: "bold",
                padding: "10px 20px",
              }}
            >
              <ReportProblemOutlinedIcon sx={{ mr: "10px" }} /> File Complaint
            </Button>
            <Button
              onClick={() => window.open("https://www.faa.gov/media/29701", "_blank")}
              sx={{
                backgroundColor: colors.orangeAccent[600],
                color: colors.grey[100],
                fontSize: "14px",
                fontWeight: "bold",
                padding: "10px 20px",
              }}
            >
              <ReportProblemOutlinedIcon sx={{ mr: "10px" }} /> Report Drone
            </Button> 
          </Box>
        </Box>
      </Box>

      {/* GRID and CHARTS, all hardcordered values will come from an sql query in v2/3 */}
      <Box
        display="grid"
        gridTemplateColumns="repeat(12, 1fr)"
        gridAutoRows="140px"
        gap="20px"
      >
        {/* ROW 1 */}
        <Box
          gridColumn="span 3"
          backgroundColor={colors.primary[400]}
          display="flex"
          alignItems="center"
          justifyContent="center"
          borderRadius="6px"
        >
          <StatBox
            title={dashboardData?.stats.monthlyFlights?.toString() || "0"}
            subtitle="Monthly Aircraft"
            progress={(dashboardData?.stats.monthlyFlights / 5000).toFixed(2)}
            increase={`${dashboardData?.stats.todayFlights || 0} today`}
            icon={
              <FlightIcon
                sx={{ color: colors.orangeAccent[600], fontSize: "26px" }}
              />
            }
          />
        </Box>
        <Box
          gridColumn="span 3"
          backgroundColor={colors.primary[400]}
          display="flex"
          alignItems="center"
          justifyContent="center"
          borderRadius="6px"
        >
          <StatBox
            title={dashboardData?.stats.todayTriggers?.toString() || "0"}
            subtitle="Triggers Today"
            progress={(dashboardData?.stats.todayTriggers / 200).toFixed(2)}
            increase={`${dashboardData?.stats.lastTriggerDb?.toFixed(1) || 0} dB last`}
            icon={
              <FlagIcon
                sx={{ color: colors.orangeAccent[600], fontSize: "26px" }}
              />
            }
          />
        </Box>
        <Box
          gridColumn="span 3"
          backgroundColor={colors.primary[400]}
          display="flex"
          alignItems="center"
          justifyContent="center"
          borderRadius="6px"
        >
          <StatBox
            title={dashboardData?.stats.jupiterTotal?.toString() || "0"}
            subtitle="Jupiter Recordings"
            progress={(dashboardData?.stats.jupiterMonth / 100).toFixed(2)}
            increase={`${dashboardData?.stats.jupiterMonth || 0} this month`}
            icon={
              <WarningIcon
                sx={{ color: colors.orangeAccent[600], fontSize: "26px" }}
              />
            }
          />
        </Box>
        <Box
          gridColumn="span 3"
          backgroundColor={colors.primary[400]}
          display="flex"
          alignItems="center"
          justifyContent="center"
          borderRadius="6px"
        >
          <StatBox
            title={`${dashboardData?.stats.uptimeHours?.toFixed(0) || 0}h`}
            subtitle="System Uptime"
            progress="0.80"
            increase={dashboardData?.status.online ? "Online" : "Offline"}
            icon={
              <CampaignIcon
                sx={{ color: colors.orangeAccent[600], fontSize: "26px" }}
              />
            }
          />
        </Box>

        {/* ROW 2 */}
        <Box
          gridColumn="span 8"
          gridRow="span 2"
          backgroundColor={colors.primary[400]}
          borderRadius="6px"
        >
          <Box
            mt="25px"
            p="0 30px"
            display="flex"
            justifyContent="space-between"
            alignItems="center"
          >
            <Box>
              <Typography
                variant="h5"
                fontWeight="600"
                color={colors.grey[100]}
              >
                Flight Activity Trends
              </Typography>
              <Typography
                variant="h3"
                fontWeight="bold"
                color={colors.orangeAccent[500]}
              >
                {dashboardData?.stats.totalFlights || "847"} Total Flights
              </Typography>
            </Box>
            <Box>
              <IconButton onClick={() => lineChartRef.current?.resetChart()}>
                <UndoIcon
                  sx={{ fontSize: "26px", color: colors.orangeAccent[500] }}
                />
              </IconButton>
            </Box>
          </Box>
          <Box height="250px" m="-20px 0 0 0">
            <LineChart isDashboard={true} ref={lineChartRef} />
          </Box>
        </Box>

        {/* TRANSACTIONS */}
        <Box
          gridColumn="span 4"
          gridRow="span 2"
          backgroundColor={colors.primary[400]}
          overflow="auto"
          borderRadius="6px"
        >
          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            borderBottom={`4px solid ${colors.primary[500]}`}
            colors={colors.grey[100]}
            p="15px"
          >
            <Typography color={colors.grey[100]} variant="h5" fontWeight="600">
              Recent Aircraft
            </Typography>
          </Box>
          {(dashboardData?.transactions || []).map((transaction, i) => (
            <Box
              key={`${transaction.txId}-${i}`}
              display="grid"
              gridTemplateColumns="1fr 100px 80px"
              alignItems="center"
              borderBottom={`4px solid ${colors.primary[500]}`}
              p="15px"
              gap="10px"
            >
              <Box>
                <Typography
                  color={colors.orangeAccent[500]}
                  variant="h5"
                  fontWeight="600"
                >
                  {transaction.txId}
                </Typography>
                <Typography color={colors.grey[100]}>
                  {transaction.user}
                </Typography>
              </Box>
              <Box color={colors.grey[100]} textAlign="center">{transaction.date}</Box>
              <Box
                backgroundColor={colors.orangeAccent[500]}
                p="5px 10px"
                borderRadius="4px"
                textAlign="center"
              >
                {transaction.cost}
              </Box>
            </Box>
          ))}
        </Box>

        {/* ROW 3 */}
        <Box
          gridColumn="span 4"
          gridRow="span 2"
          backgroundColor={colors.primary[400]}
          p="30px"
          borderRadius="6px"
        >
          <Typography variant="h5" fontWeight="600">
            Eagles Disturbed This Quarter
          </Typography>
          <Tooltip
            title="Q1 2024 Wildlife Impact • Target: Under 25 eagles • Previous Quarter: 31 eagles • Protection Status: Active"
            placement="top"
            arrow
            componentsProps={{
              tooltip: {
                sx: {
                  fontSize: '14px',
                  padding: '12px 16px',
                  maxWidth: '400px'
                }
              }
            }}
          >
            <Box
              display="flex"
              flexDirection="column"
              alignItems="center"
              mt="25px"
              sx={{ cursor: "help" }}
            >
              <ProgressCircle size="125" />
              <Typography
                variant="h5"
                color={colors.orangeAccent[500]}
                sx={{ mt: "15px" }}
              >
                {dashboardData?.stats.eaglesDisturbed || "23"} Eagles Disturbed
              </Typography>
              <Typography>Wildlife Protection Active</Typography>
            </Box>
          </Tooltip>
        </Box>

        {/* Final boxes */}
        <Box
          gridColumn="span 4"
          gridRow="span 2"
          backgroundColor={colors.primary[400]}
          borderRadius="6px"
        >
          <Typography
            variant="h5"
            fontWeight="600"
            sx={{ padding: "30px 30px 0 30px" }}
          >
            Complaint Process Status
          </Typography>
          <Box height="250px" mt="-20px">
            <PieChart isDashboard={true} />
          </Box>
        </Box>
        {/* Last box */}
        <Box
          gridColumn="span 4"
          gridRow="span 2"
          backgroundColor={colors.primary[400]}
          padding="30px"
          borderRadius="6px"
        >
          <Typography
            variant="h5"
            fontWeight="600"
            sx={{ marginBottom: "15px" }}
          >
            Violations by Aircraft Type
          </Typography>
          <Box height="200px">
            <BarChart isDashboard={true} />
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

export default Dashboard;
