// Fetch real metrics from S3
const S3_METRICS_URL = 'https://skysentinel-dashboard-metrics.s3.us-west-2.amazonaws.com/latest.json';

export const fetchDashboardData = async (timeRange = "24h") => {
  try {
    const response = await fetch(S3_METRICS_URL);
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    const data = await response.json();
    
    // Transform S3 metrics to dashboard format
    return {
      stats: {
        // Aircraft metrics
        monthlyFlights: data.metrics?.aircraft?.month || 0,
        todayFlights: data.metrics?.aircraft?.today || 0,
        yesterdayFlights: data.metrics?.aircraft?.yesterday || 0,
        totalFlights: data.metrics?.aircraft?.total || 0,
        
        // Triggers
        todayTriggers: data.metrics?.triggers?.today || 0,
        monthTriggers: data.metrics?.triggers?.month || 0,
        lastTriggerDb: data.metrics?.triggers?.last_trigger_db || 0,
        
        // Jupiter recordings
        jupiterToday: data.metrics?.jupiter?.today || 0,
        jupiterMonth: data.metrics?.jupiter?.month || 0,
        jupiterTotal: data.metrics?.jupiter?.total || 0,
        
        // Storm verdicts
        truthForged: data.metrics?.storm_verdicts?.truth_forged || 0,
        aircraftVerified: data.metrics?.storm_verdicts?.aircraft || 0,
        unknown: data.metrics?.storm_verdicts?.unknown || 0,
        
        // System
        dbThreshold: data.metrics?.system?.db_threshold || 75.0,
        uptimeHours: data.metrics?.system?.uptime_hours || 0,
        
        // Legacy fields (keep for compatibility)
        violations2000ft: 0,
        violations1000ft: 0,
        violations500ft: 0,
        eaglesDisturbed: 0
      },
      status: {
        online: data.status?.online || false,
        lastHeartbeat: data.status?.last_heartbeat || null,
        deviceId: data.device_id || 'unknown'
      },
      lastUpdated: new Date(data.timestamp).toLocaleString(),
      timestamp: data.timestamp,
      transactions: [], // TODO: Add recent aircraft list
      barData: [], // TODO: Add chart data
      pieData: [], // TODO: Add chart data
      lineData: [] // TODO: Add chart data
    };
  } catch (error) {
    console.error('Failed to fetch metrics from S3:', error);
    // Return empty data on error
    return {
      stats: {
        monthlyFlights: 0,
        todayFlights: 0,
        totalFlights: 0,
        violations2000ft: 0,
        violations1000ft: 0,
        violations500ft: 0,
        eaglesDisturbed: 0
      },
      status: { online: false },
      lastUpdated: 'Error loading data',
      transactions: [],
      barData: [],
      pieData: [],
      lineData: []
    };
  }
};